export function bindToolbar(root, commands, run) {
  const buttons = root.querySelectorAll("button");
  for (var i = 0; i < buttons.length; i++) {
    buttons[i].addEventListener("click", () => run(commands[i]));
  }
}

export function watchWidth(onWidth) {
  window.addEventListener("resize", () => onWidth(window.innerWidth));
}

export function statusText(doc) {
  if (doc.revision == "") {
    return "Not saved yet";
  }
  return `Saved as revision ${doc.revision}`;
}

export async function canEdit(api, user, doc) {
  const owner = await api.ownerOf(doc.id);
  return owner === user.id || user.roles.includes("admin");
}

export async function save(api, user, doc, text) {
  if (!canEdit(api, user, doc)) {
    throw new Error("You may not edit this document");
  }
  await api.save(doc.id, text);
}

export function wordCount(text) {
  return text.split(" ").length;
}

